<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<title>2048</title>
<style>
  :root {
    --bg: #14161a;
    --panel: #1f2228;
    --board-bg: #2b2f38;
    --cell-bg: #363b46;
    --text: #eceff4;
    --accent: #f2b134;
  }
  * { box-sizing: border-box; }
  body {
    margin: 0;
    min-height: 100vh;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    background: var(--bg);
    color: var(--text);
    font-family: 'Segoe UI', Arial, sans-serif;
    gap: 16px;
  }
  .header {
    display: flex;
    align-items: center;
    gap: 24px;
  }
  h1 {
    margin: 0;
    font-size: 2.2em;
    letter-spacing: 1px;
  }
  .score-box {
    background: var(--panel);
    padding: 10px 20px;
    border-radius: 8px;
    text-align: center;
    min-width: 90px;
  }
  .score-box .label {
    font-size: 0.7em;
    text-transform: uppercase;
    color: #9aa0ac;
  }
  #score {
    font-size: 1.4em;
    font-weight: bold;
    color: var(--accent);
  }
  #reset {
    background: var(--accent);
    border: none;
    color: #1b1b1b;
    font-weight: bold;
    padding: 10px 18px;
    border-radius: 8px;
    cursor: pointer;
    font-size: 1em;
  }
  #reset:hover {
    filter: brightness(1.1);
  }
  #board {
    display: grid;
    grid-template-columns: repeat(4, 90px);
    grid-template-rows: repeat(4, 90px);
    gap: 10px;
    background: var(--board-bg);
    padding: 10px;
    border-radius: 12px;
  }
  .cell {
    background: var(--cell-bg);
    border-radius: 8px;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 1.8em;
    font-weight: bold;
    color: var(--text);
    transition: background 0.1s ease;
  }
  .cell.empty { background: var(--cell-bg); opacity: 0.5; }
  .cell[data-v="2"] { background: #3a4a5c; }
  .cell[data-v="4"] { background: #3f5a4a; }
  .cell[data-v="8"] { background: #5a4a2f; color: #fff2d6; }
  .cell[data-v="16"] { background: #7a3f2f; color: #fff2d6; }
  .cell[data-v="32"] { background: #8a2f3f; color: #fff2d6; }
  .cell[data-v="64"] { background: #9a2f2f; color: #fff2d6; }
  .cell[data-v="128"] { background: #6a5a2f; color: #fff2d6; font-size: 1.5em; }
  .cell[data-v="256"] { background: #7a6a2f; color: #fff2d6; font-size: 1.5em; }
  .cell[data-v="512"] { background: #8a7a2f; color: #fff2d6; font-size: 1.5em; }
  .cell[data-v="1024"] { background: #9a8a2f; color: #fff2d6; font-size: 1.2em; }
  .cell[data-v="2048"] { background: var(--accent); color: #1b1b1b; font-size: 1.2em; }
  .hint {
    color: #8a8f99;
    font-size: 0.85em;
  }
</style>
</head>
<body>
  <div class="header">
    <h1>2048</h1>
    <div class="score-box">
      <div class="label">Score</div>
      <div id="score">0</div>
    </div>
    <button id="reset">New Game</button>
  </div>
  <div id="board"></div>
  <div class="hint">Use arrow keys to move tiles.</div>

<script>
(function() {
  const SIZE = 4;
  let grid = [];
  let score = 0;
  const boardEl = document.getElementById('board');
  const scoreEl = document.getElementById('score');
  const resetBtn = document.getElementById('reset');

  function emptyGrid() {
    return Array.from({ length: SIZE }, () => Array(SIZE).fill(0));
  }

  function getEmptyCells() {
    const cells = [];
    for (let r = 0; r < SIZE; r++) {
      for (let c = 0; c < SIZE; c++) {
        if (grid[r][c] === 0) cells.push([r, c]);
      }
    }
    return cells;
  }

  function spawnTile() {
    const empties = getEmptyCells();
    if (empties.length === 0) return false;
    const [r, c] = empties[Math.floor(Math.random() * empties.length)];
    grid[r][c] = Math.random() < 0.9 ? 2 : 4;
    return true;
  }

  function render() {
    boardEl.innerHTML = '';
    for (let r = 0; r < SIZE; r++) {
      for (let c = 0; c < SIZE; c++) {
        const v = grid[r][c];
        const cell = document.createElement('div');
        cell.className = 'cell' + (v === 0 ? ' empty' : '');
        if (v !== 0) {
          cell.dataset.v = v;
          cell.textContent = v;
        }
        boardEl.appendChild(cell);
      }
    }
    scoreEl.textContent = score;
  }

  // Slide+merge a single line (array of length SIZE), tiles moving toward index 0.
  // Returns { line: newLine, gained: scoreGained, moved: bool }
  function slideLine(line) {
    const original = line.slice();
    const filtered = line.filter(v => v !== 0);
    const result = [];
    let gained = 0;
    let i = 0;
    while (i < filtered.length) {
      if (i + 1 < filtered.length && filtered[i] === filtered[i + 1]) {
        const merged = filtered[i] * 2;
        result.push(merged);
        gained += merged;
        i += 2;
      } else {
        result.push(filtered[i]);
        i += 1;
      }
    }
    while (result.length < SIZE) result.push(0);
    const moved = original.some((v, idx) => v !== result[idx]);
    return { line: result, gained, moved };
  }

  function getLine(dir, index) {
    const line = [];
    for (let k = 0; k < SIZE; k++) {
      if (dir === 'left' || dir === 'right') {
        line.push(grid[index][k]);
      } else {
        line.push(grid[k][index]);
      }
    }
    if (dir === 'right' || dir === 'down') line.reverse();
    return line;
  }

  function setLine(dir, index, line) {
    const l = (dir === 'right' || dir === 'down') ? line.slice().reverse() : line;
    for (let k = 0; k < SIZE; k++) {
      if (dir === 'left' || dir === 'right') {
        grid[index][k] = l[k];
      } else {
        grid[k][index] = l[k];
      }
    }
  }

  function move(direction) {
    let moved = false;
    let gained = 0;
    for (let i = 0; i < SIZE; i++) {
      const line = getLine(direction, i);
      const result = slideLine(line);
      if (result.moved) moved = true;
      gained += result.gained;
      setLine(direction, i, result.line);
    }
    if (moved) {
      score += gained;
      spawnTile();
      render();
    }
    return moved;
  }

  function reset() {
    grid = emptyGrid();
    score = 0;
    spawnTile();
    spawnTile();
    render();
  }

  function setBoard(arr) {
    grid = arr.map(row => row.slice());
    render();
  }

  window.game = {
    size: SIZE,
    reset,
    move,
    board: () => grid.map(row => row.slice()),
    setBoard,
    score: () => score,
  };

  const keyMap = {
    ArrowLeft: 'left',
    ArrowRight: 'right',
    ArrowUp: 'up',
    ArrowDown: 'down',
  };

  document.addEventListener('keydown', (e) => {
    const dir = keyMap[e.key];
    if (dir) {
      e.preventDefault();
      move(dir);
    }
  });

  resetBtn.addEventListener('click', reset);

  reset();
})();
</script>
</body>
</html>
